      next = {19}
    },
    [19] = {
      beijing = 52760,
      card_cg_anim = "none",
      dialog = 2,
      idx = 5,
      male = 2,
      music = "1012_2023Halloween",
      renming = "Simon",
      renwu = "npc",
      sentence = "Perhaps I should instigate an impeachment, or stage a mutiny, and get myself crowned by the blood of countless others?",
      voice = 2,
      next = {20}
    },
    [20] = {
      beijing = 52760,
      card_cg_anim = "none",
      dialog = 2,
      idx = 5,
      male = 2,
      music = "1012_2023Halloween",
      renming = "Simon",
      renwu = "npc",
      sentence = "But what to do about my wife?",
      voice = 2,
      next = {21}
    },
    [21] = {
      beijing = 52760,
      card_cg_anim = "none",
      dialog = 2,
      idx = 5,
      male = 2,
      music = "1012_2023Halloween",
      renming = "Simon",
      renwu = "npc",
      sentence = "That poor little princess is too delicate and weak. The only thing her ears can tolerate is angelic harp music. The noise of weapons would frighten her out of her wits.",
      voice = 2,
      next = {22}
    },
    [22] = {
      beijing = 52760,
      card_cg_anim = "CG_421083_22_1",
      dialog = 3,
      music = "1012_2023Halloween",
      renwu = "npc",
      sentence = "The measured cadence of his words was saturated with a cruel iciness that penetrated my limbs to the bone.",
