      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      role6 = 21635006,
      ruchang = -1,
      sentence = "Wait, I've got it.",
      voice = 2,
      next = {25}
    },
    [25] = {
      beijing = 4837,
      dialog = 3,
      music = "1012_2023Halloween",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202202,
      role6 = 21635006,
      sentence = "Simon tossed away his scepter on stage, and then like a magic trick, there was suddenly a bouquet of mesmerizing flowers in his hand.",
      next = {26}
    },
    [26] = {
      beijing = 4837,
      dialog = 3,
