      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202202,
      role6 = 21635006,
      sentence = "Oleander, wolf's bane, jessamine... each one was a beautiful poisonous flower Lucien had told me about before.",
      next = {27}
    },
    [27] = {
      beijing = 4837,
      dialog = 2,
      idx = 5,
      male = 2,
