      renming = "Simon",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202202,
      role6 = 21635006,
      sentence = "A witch from the Orient once imparted to me an unknown concoction. The colorless and odorless powder will surely assist me in realizing my dream.",
      voice = 2,
      next = {28}
    },
    [28] = {
      beijing = 4837,
      dialog = 2,
      idx = 5,
