    },
    [31] = {
      beijing = 4733,
      dialog = 3,
      mask = "memory",
      music = "1012_2023Halloween",
      renwu = "npc",
      sentence = "That day, Lucien held a feast and invited my father and the Duke. I couldn't attend due to a sudden fever.",
