    },
    [32] = {
      beijing = 4733,
      dialog = 3,
      mask = "memory",
      music = "1012_2023Halloween",
      renwu = "npc",
      sentence = "After the feast, in my debilitated state, I received horrifying news...",
      next = {33}
    },
    [33] = {
      beijing = 4733,
      dialog = 3,
      mask = "memory",
      music = "1012_2023Halloween",
      renwu = "npc",
      sentence = "My father had died at the dinner table, and my husband—now exposed for plotting to poison the Duke and the King—was executed on the spot by the Duke, who had managed to survive.",
