    },
    [35] = {
      beijing = 4733,
      dialog = 3,
      mask = "memory",
      music = "1012_2023Halloween",
      renwu = "npc",
      sentence = "But that was a secret of the royal family. I had never spoken of it with Simon, so where did he learn of it?!",
      next = {36}
    },
    [36] = {
      beijing = 4837,
      bganim = 1,
      dialog = 3,
      music = "1012_2023Halloween",
      renwu = "npc",
      sentence = "By now, the music for the second act was playing. The lights were dimmed, and that lethal dinner table was moved onto the stage.",
