    },
    [37] = {
      beijing = 4837,
      dhead = 116,
      dialog = 1,
      music = "1012_2023Halloween",
      renming = "$u",
      renwu = "npc",
      sentence = "No…!",
      next = {38}
    },
    [38] = {
      beijing = 4837,
      dialog = 3,
      music = "22_Despair",
      renwu = "npc",
      sentence = "I jumped up, finally unable to take it any longer. Stumbling over myself, I rushed out of the theater.",
