    },
    [50] = {
      beijing = 3180,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "Thoughts were a tangled mess in my mind, and in the midst of the chaos, that most secret and dreadful of thoughts welled up beyond my control.",
