    },
    [51] = {
      beijing = 3180,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "—Perhaps there never was an actor named \"Simon\" who traveled from the Orient. Perhaps there was only...",
