    },
    [53] = {
      beijing = 3180,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "After who knows how much time passed, the door of my room was pushed open, and a candle lit up the darkness.",
