    },
    [55] = {
      beijing = 3180,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      sentence = "I couldn't say anything. My whole body had been stiff for so long, even my teeth stung with pain.",
      next = {56}
    },
    [56] = {
      beijing = 3180,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      ruchang = -1,
      sentence = "The source of light drew nearer. Simon had changed out of his stage costume, and he wore an expression so gentle, as if none of that had just happened.",
      next = {57}
    },
    [57] = {
      beijing = 3180,
      dialog = 2,
      idx = 5,
      male = 2,
      music = "12_Sorrow_Short_Ver",
      renming = "Simon",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      sentence = "You used to be just like this. Any time you took a fright, you'd snuff out all the lights and curl up in bed, not moving a muscle.",
      voice = 2,
      next = {58}
    },
    [58] = {
      beijing = 3180,
      dialog = 2,
      idx = 5,
      male = 2,
      music = "12_Sorrow_Short_Ver",
      renming = "Simon",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      sentence = "Every time, it would take me so long to get you to come around. I'd use sweets or kisses to coax you before you'd come out, like a little bunny popping out of the ground.",
      voice = 2,
      next = {59}
    },
    [59] = {
      beijing = 3180,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.1,
      sentence = "He put down the candle and slowly leaned toward me, his voice so tender that it felt like I could drown in it.",
      next = {60}
    },
    [60] = {
      beijing = 3180,
      dialog = 2,
      idx = 5,
      male = 2,
      music = "12_Sorrow_Short_Ver",
      renming = "Simon",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.1,
      sentence = "Actually, that wasn't the play that I had originally prepared; but because there was an extra, unintended audience member, I had no choice but to perform that story.",
      voice = 2,
      next = {61}
    },
    [61] = {
      beijing = 3180,
      dialog = 2,
      idx = 5,
      male = 2,
      music = "12_Sorrow_Short_Ver",
      renming = "Simon",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.1,
      sentence = "I'm sorry. Did I make you feel scared tonight?",
      voice = 2,
      next = {62}
    },
    [62] = {
      beijing = 3180,
      dialog = 3,
      music = "12_Sorrow_Short_Ver",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.1,
      sentence = "When I opened my mouth, it was as if I had forgotten how to speak. A moment later, I managed to spit out the words:",
