      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202202,
      roleanim = 1.1,
      sentence = "I thought, after all I'd taught you, you should be able to taste it... Tonight at the party, your wine was poisoned by someone.",
