    },
    [73] = {
      beijing = 3180,
      dialog = 3,
      music = "205_XuMo_Second",
      renwu = "npc",
      sentence = "His cool calm completely ignited my rage. I threw off the blanket and lunged at him.",
      next = {74}
    },
    [74] = {
      beijing = 3180,
      dialog = 3,
      music = "205_XuMo_Second",
      renwu = "npc",
      sentence = "Simon was caught off guard, and I pinned him to the bed.",
