    },
    [75] = {
      beijing = 3180,
      dialog = 3,
      music = "205_XuMo_Second",
      renwu = "npc",
      sentence = "The rage at being toyed with drowned out my reason. The only thing I wanted was to repay these years of torment that I'd suffered back upon him.",
      next = {76}
    },
    [76] = {
      beijing = 3180,
      dialog = 3,
      music = "205_XuMo_Second",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.2,
      ruchang = -1,
      sentence = "But my body was entirely too feeble. My attacks on him were unfortunately nothing more than bedroom horseplay. With hardly any effort, he had my wrists held in place.",
      next = {77}
    },
    [77] = {
      beijing = 3180,
      dialog = 2,
      idx = 5,
      male = 2,
      music = "205_XuMo_Second",
      renming = "Simon",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.2,
      sentence = "Easy. Now is not the time to lose one's temper.",
      voice = 2,
      next = {78}
    },
    [78] = {
      beijing = 3180,
      dialog = 3,
      music = "205_XuMo_Second",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.2,
      sentence = "Without needing to put on fine clothes, Simon's voice recovered that leisurely tone befitting one of high status.",
