    },
    [79] = {
      beijing = 3180,
      dialog = 3,
      music = "205_XuMo_Second",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.2,
      sentence = "It was the voice he had used to soothe me, kiss me, and make me fall willingly into his web.",
      next = {80}
    },
    [80] = {
      beijing = 3180,
      dialog = 3,
      music = "205_XuMo_Second",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.2,
