  [431193] = {
    [1] = {
      beijing = 2249,
      dialog = 3,
      music = "64_2020anniversary_carnival",
      renwu = "npc",
      sentence = "After re-entering the convention hall in our new identities, we were swallowed up by a fervor and excitement different from a typical concert.",
      next = {2}
    },
    [2] = {
      beijing = 2249,
      dialog = 3,
      music = "64_2020anniversary_carnival",
      renwu = "npc",
      sentence = "With the helmet and armor, Kiro was just like any other person attending the comicon. Just a normal person indulging in his hobby.",
      next = {3}
    },
    [3] = {
      beijing = 2249,
      dialog = 3,
      music = "64_2020anniversary_carnival",
      renwu = "npc",
      sentence = "He gently pushed open his helmet visor a bit. His eyes brimming with light lit up my heart too.",
      next = {4}
    },
    [4] = {
      beijing = 2249,
      dhead = 113,
      dialog = 1,
      music = "64_2020anniversary_carnival",
      renming = "$u",
      renwu = "npc",
      sentence = "Someone seems especially happy~",
      next = {5}
    },
    [5] = {
      beijing = 2249,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "64_2020anniversary_carnival",
      renming = "Kiro",
      renwu = "npc",
      role1 = 3164000,
      role2 = 302101,
      role3 = 302205,
      ruchang = -1,
      sentence = "I think \"happy\" doesn't begin to describe how I'm feeling. After all, I don't get many chances to check out a convention like this!",
      voice = 2,
      next = {6}
    },
    [6] = {
      beijing = 2249,
      dialog = 2,
      idx = 5,
      music = "64_2020anniversary_carnival",
      renming = "??",
      renwu = "npc",
      role1 = 3164000,
      role2 = 302108,
      role3 = 302205,
      sentence = "Hello, do you think I could get a picture of you two?",
      next = {7}
    },
    [7] = {
      beijing = 2249,
      dialog = 3,
      music = "64_2020anniversary_carnival",
      renwu = "npc",
      sentence = "A youngish-sounding male voice spoke up behind us, making me turn my head.",
      next = {8}
    },
    [8] = {
      beijing = 2249,
      dialog = 3,
      music = "64_2020anniversary_carnival",
      renwu = "npc",
      sentence = "Several boys and girls seeming to be high school students were looking hopefully at us, and the one who had spoken to us just now was waving a camera in his hand.",
      next = {9}
    },
    [9] = {
      beijing = 2249,
      dialog = 3,
      music = "64_2020anniversary_carnival",
      renwu = "npc",
      sentence = "I looked at Kiro next to me. He nodded with his helmeted head and said in a raspy voice:",
      next = {10}
    },
    [10] = {
      beijing = 2249,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "64_2020anniversary_carnival",
      renming = "Kiro",
      renwu = "npc",
      role1 = 3164000,
      role2 = 302108,
      role3 = 302205,
      sentence = "Sure thing.",
      voice = 2,
      next = {11}
    },
    [11] = {
      beijing = 2249,
      dialog = 2,
      idx = 5,
      music = "64_2020anniversary_carnival",
      renming = "Young Man",
      renwu = "npc",
      sentence = "Thanks!",
      next = {12}
    },
    [12] = {
      beijing = 2249,
      dialog = 3,
      music = "64_2020anniversary_carnival",
      renwu = "npc",
      sentence = "Kiro put a hand around my waist and wrapped his other hand on the hilt of his sword.",
      next = {13}
    },
    [13] = {
      beijing = 2249,
      dialog = 3,
      music = "64_2020anniversary_carnival",
      renwu = "npc",
      sentence = "I suddenly realized that he was imitating a classic kiss pose from the comic book, and I instantly played along, getting up on my tiptoes and planting a kiss on his cheek through the helmet.",
      next = {14}
    },
    [14] = {
      beijing = 2249,
      dialog = 3,
      music = "64_2020anniversary_carnival",
      renwu = "npc",
      sentence = "I heard the click of the camera shutter, and out of the corner of my eye, I saw even more people gather around and point their cameras at us.",
      next = {15}
    },
    [15] = {
      beijing = 2249,
      dialog = 3,
      music = "64_2020anniversary_carnival",
      renwu = "npc",
      sentence = "As I struck the comic book pose, I whispered into his ear:",
      next = {16}
    },
    [16] = {
      beijing = 2249,
      dhead = 112,
      dialog = 1,
      music = "64_2020anniversary_carnival",
      renming = "$u",
      renwu = "npc",
      sentence = "Good thing I boned up on the comic books beforehand, otherwise I wouldn't know how to play along with you...",
      next = {17}
    },
    [17] = {
      beijing = 2249,
      dhead = 112,
      dialog = 1,
      music = "64_2020anniversary_carnival",
      renming = "$u",
      renwu = "npc",
      sentence = "You don't think I'll seem like a poser, do you?",
      next = {18}
    },
    [18] = {
      beijing = 2249,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "64_2020anniversary_carnival",
      renming = "Kiro",
      renwu = "npc",
      role1 = 3164000,
      role2 = 302101,
      role3 = 302205,
      sentence = "I don't see how.",
      voice = 2,
      next = {19}
    },
    [19] = {
      beijing = 2249,
      dialog = 3,
      music = "64_2020anniversary_carnival",
      renwu = "npc",
      role1 = 3164000,
      role2 = 302101,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "There was a lilt of laughter to his voice. Seeing me up on my tiptoes, he pulled me into another pose, getting on one knee in front of me.",
      next = {20}
    },
    [20] = {
      beijing = 2249,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "64_2020anniversary_carnival",
      renming = "Kiro",
      renwu = "npc",
      role1 = 3164000,
      role2 = 302101,
      role3 = 302205,
      roleanim = 1.1,
      sentence = "As long as you've seen the work and you like the work, you are 100% a bona fide \"fan\" to me. Nothing \"poser\" about it at all.",
      voice = 2,
      next = {21}
    },
    [21] = {
      beijing = 2249,
      dhead = 112,
